import React from 'react';
import { ChevronDown, GraduationCap, Building2, Key, Info, FileText, Newspaper, BookOpen } from 'lucide-react';

const quickLinks = [
    { name: 'FACILITIES', icon: Building2, color: 'bg-[#C5A365] hover:bg-[#b09158]', hasDropdown: true },
    { name: 'ADMISSION', icon: GraduationCap, color: 'bg-[#A32020] hover:bg-[#8b1a1a]', hasDropdown: false },
    { name: 'HOSTEL', icon: Building2, color: 'bg-[#C5A365] hover:bg-[#b09158]', hasDropdown: false },
    { name: 'LOGIN', icon: Key, color: 'bg-[#C5A365] hover:bg-[#b09158]', hasDropdown: true },
    { name: 'DISCLOSURES', icon: Info, color: 'bg-[#C5A365] hover:bg-[#b09158]', hasDropdown: false },
    { name: 'BLOG', icon: FileText, color: 'bg-[#C5A365] hover:bg-[#b09158]', hasDropdown: false },
    { name: 'NEWS-EVENTS', icon: Newspaper, color: 'bg-[#C5A365] hover:bg-[#b09158]', hasDropdown: false },
    { name: 'CENTRAL LIBRARY', icon: BookOpen, color: 'bg-[#C5A365] hover:bg-[#b09158]', hasDropdown: false },
];

const announcements = [
    "New Result - B.Tech S6 (S) Exam, November 2025 (2022 Scheme)",
    "New Result - B.Tech S1 (R) Exam, December 2025 (2023 Scheme)",
    "Registration open for Annual Technical Fest 2025",
    "Notification regarding odd semester fee payment",
    "Guidelines for B.Tech Honors Registration published",
];

const upcomingEvents = [
    "» College of Engineering Chengannur is organizing the National Conference on Emerging Technologies from 19th to 21st December 2025.",
    "» The Department of Computer Science is organizing a Six-day AICTE Training and Learning (ATAL) Online Faculty Development Programme.",
    "» Annual Techfest 'Drishti 2025' dates announced.",
];

const events = [
    "» The 7th International Conference on Modelling and Simulation",
    "» Summer internship program - Computer Science Dept",
    "» Internship on Optical Communication Design with Opticystem",
    "» Workshop on Advanced AI and Machine Learning",
];

// Helper to duplicate items for smooth infinite scrolling
const ScrollList = ({ items }) => (
    <div className="relative h-[250px] w-full overflow-hidden px-4">
        <div className="absolute top-0 w-full animate-scroll-up group hover:[animation-play-state:paused]">
            <ul className="flex flex-col gap-6 pb-6 pt-4 pr-6">
                {items.map((item, idx) => (
                    <li key={`first-${idx}`} className="text-[0.9rem] leading-snug text-slate-800 border-b border-slate-100 pb-3 last:border-0 cursor-pointer hover:text-coral transition-colors">
                        {item}
                    </li>
                ))}
            </ul>
            <ul className="flex flex-col gap-6 pb-6 pr-6" aria-hidden="true">
                {items.map((item, idx) => (
                    <li key={`second-${idx}`} className="text-[0.9rem] leading-snug text-slate-800 border-b border-slate-100 pb-3 last:border-0 cursor-pointer hover:text-coral transition-colors">
                        {item}
                    </li>
                ))}
            </ul>
        </div>
    </div>
);

const NoticeUpdates = () => {
    return (
        <section className="relative w-full bg-[#f4f4f4] py-8 overflow-hidden" style={{ backgroundImage: 'radial-gradient(#e5e7eb 1px, transparent 1px)', backgroundSize: '20px 20px' }}>
            {/* Quick Links Row */}
            <div className="mx-auto max-w-[1440px] px-4 lg:px-8 mb-10">
                <div className="flex flex-wrap justify-center gap-3">
                    {quickLinks.map((link, idx) => (
                        <button key={idx} className={`flex items-center gap-2 px-5 py-2.5 rounded-[4px] text-white font-semibold text-[0.8rem] transition-colors ${link.color} shadow-sm border border-black/10`}>
                            <link.icon size={16} className="opacity-90" />
                            <span>{link.name}</span>
                            {link.hasDropdown && <ChevronDown size={14} className="ml-1 opacity-80" />}
                        </button>
                    ))}
                </div>
            </div>

            {/* 3 Columns Board */}
            <div className="mx-auto max-w-[1440px] px-4 lg:px-8">
                <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                    {/* Announcement */}
                    <div className="bg-white rounded-xl shadow-sm border border-slate-200 overflow-hidden">
                        <div className="bg-white border-b border-slate-100 py-4 text-center">
                            <h3 className="font-display text-[1.2rem] font-bold text-[#8a4a23]">Announcement</h3>
                        </div>
                        <ScrollList items={announcements} />
                    </div>

                    {/* Upcoming Events */}
                    <div className="bg-white rounded-xl shadow-sm border border-slate-200 overflow-hidden">
                        <div className="bg-white border-b border-slate-100 py-4 text-center">
                            <h3 className="font-display text-[1.2rem] font-bold text-[#8a4a23]">Upcoming Events</h3>
                        </div>
                        <ScrollList items={upcomingEvents} />
                    </div>

                    {/* Events */}
                    <div className="bg-white rounded-xl shadow-sm border border-slate-200 overflow-hidden">
                        <div className="bg-white border-b border-slate-100 py-4 text-center">
                            <h3 className="font-display text-[1.2rem] font-bold text-[#8a4a23]">Events</h3>
                        </div>
                        <ScrollList items={events} />
                    </div>
                </div>
            </div>
        </section>
    );
};

export default NoticeUpdates;
